# frozen_string_literal: true

require_relative "../base"

module CLI
  class Docker < Base
    # Shared by every bin/dx subcommand
    #
    class Command < Base
      IMAGE_NAME   = "passerelle:ruby-4.0"
      PROJECT_NAME = "passerelle"

      # Generated by `bin/dx build` to save the image & project names
      # used by other `bin/dx` commands.
      #
      ENV_FILE = ".docker/docker-compose.dev.env"

      private

      def ensure_docker_installed
        return if command_available?("docker")

        say "Docker is not installed."
        say "Please visit https://docs.docker.com/get-docker/"
        abort
      end

      # Tells `docker compose` which compose file makes up the project and
      # which env-file feeds its variable substitution.
      #
      # Env-files are only included when present: `docker compose --env-file`
      # hard-fails on a missing file.
      #
      def compose
        command  = ["docker compose", "--file docker-compose.dev.yml"]
        command << "--env-file #{ENV_FILE}" if File.exist?(ENV_FILE)
        command.join(" ")
      end
    end
  end
end
